class I18nManager {
  constructor() {
    this.currentLang = localStorage.getItem('recollect_lang') || 'en';
    this.isSpeaking = false;
    this.audioCtx = null;
    
    if ('speechSynthesis' in window) {
      window.speechSynthesis.onvoiceschanged = () => {};
    }
  }

  setLanguage(lang) {
    if (RECOLLECT_I18N[lang]) {
      this.currentLang = lang;
      localStorage.setItem('recollect_lang', lang);
      this.updateDOM();
      
      const s1 = document.getElementById('langSelect');
      if (s1 && s1.value !== lang) s1.value = lang;
      const s2 = document.getElementById('settingsLangSelect');
      if (s2 && s2.value !== lang) s2.value = lang;

      if (window.app && typeof window.app.updateOrientationTime === 'function') {
        window.app.updateOrientationTime();
      }
      if (window.app && typeof window.app.applyLanguageToAllViews === 'function') {
        window.app.applyLanguageToAllViews();
      }

      window.dispatchEvent(new CustomEvent('recollect:langchange', { detail: { lang } }));
    }
  }

  getText(key, replacements = {}) {
    const langDict = RECOLLECT_I18N[this.currentLang] || RECOLLECT_I18N.en;
    let text = langDict[key] || (RECOLLECT_I18N.en && RECOLLECT_I18N.en[key]) || key;
    
    if (typeof text === 'string' && replacements) {
      Object.keys(replacements).forEach(k => {
        text = text.replace(new RegExp(`\\{${k}\\}`, 'g'), replacements[k]);
      });
    }
    return text;
  }

  t(key, replacements = {}) {
    return this.getText(key, replacements);
  }

  getFormattedDate(date = new Date()) {
    const langDict = RECOLLECT_I18N[this.currentLang] || RECOLLECT_I18N.en;
    const dayName = langDict.days ? langDict.days[date.getDay()] : date.toLocaleDateString('en-US', { weekday: 'long' });
    const monthName = langDict.months ? langDict.months[date.getMonth()] : date.toLocaleDateString('en-US', { month: 'long' });
    const dayNum = date.getDate();

    if (this.currentLang === 'as' || this.currentLang === 'bn' || this.currentLang === 'hi' || this.currentLang === 'kha') {
      return `${dayName}, ${dayNum} ${monthName}`;
    }
    return `${dayName}, ${monthName} ${dayNum}`;
  }

  getTimeOfDayGreetingKey(hour = new Date().getHours()) {
    if (hour >= 5 && hour < 12) return 'greeting_morning';
    if (hour >= 12 && hour < 17) return 'greeting_afternoon';
    if (hour >= 17 && hour < 21) return 'greeting_evening';
    return 'greeting_night';
  }

  getTimeOfDayWeatherKey(hour = new Date().getHours()) {
    if (hour >= 5 && hour < 12) return 'weather_morning';
    if (hour >= 12 && hour < 17) return 'weather_afternoon';
    if (hour >= 17 && hour < 21) return 'weather_evening';
    return 'weather_night';
  }

  updateDOM() {
    // 1. Element text content
    document.querySelectorAll('[data-i18n]').forEach(el => {
      const key = el.getAttribute('data-i18n');
      const val = this.getText(key);
      if (val && val !== key) {
        el.textContent = val;
      }
    });

    // 2. Input / Textarea Placeholders
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
      const key = el.getAttribute('data-i18n-placeholder');
      const val = this.getText(key);
      if (val && val !== key) {
        el.setAttribute('placeholder', val);
      }
    });

    // 3. Tooltip / title attributes
    document.querySelectorAll('[data-i18n-title]').forEach(el => {
      const key = el.getAttribute('data-i18n-title');
      const val = this.getText(key);
      if (val && val !== key) {
        el.setAttribute('title', val);
      }
    });

    // 4. Aria label attributes
    document.querySelectorAll('[data-i18n-aria]').forEach(el => {
      const key = el.getAttribute('data-i18n-aria');
      const val = this.getText(key);
      if (val && val !== key) {
        el.setAttribute('aria-label', val);
      }
    });
  }

  speakText(text, onComplete) {
    if (!('speechSynthesis' in window)) {
      this.playMelodicChime(onComplete);
      return;
    }

    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    
    const langVoiceMap = {
      'en': 'en-IN',
      'hi': 'hi-IN',
      'bn': 'bn-IN',
      'as': 'as-IN',
      'kha': 'en-IN'
    };
    
    utterance.lang = langVoiceMap[this.currentLang] || 'en-IN';
    utterance.rate = 0.85;
    utterance.pitch = 1.05;

    const voices = window.speechSynthesis.getVoices();
    const targetVoice = voices.find(v => v.lang.startsWith(utterance.lang) || v.lang.includes(utterance.lang.split('-')[0]));
    if (targetVoice) {
      utterance.voice = targetVoice;
    }

    this.isSpeaking = true;
    utterance.onend = () => {
      this.isSpeaking = false;
      if (onComplete) onComplete();
    };
    utterance.onerror = () => {
      this.isSpeaking = false;
      this.playMelodicChime(onComplete);
    };

    try {
      window.speechSynthesis.speak(utterance);
    } catch (err) {
      this.playMelodicChime(onComplete);
    }
  }

  playMelodicChime(onComplete) {
    try {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) {
        if (onComplete) onComplete();
        return;
      }
      if (!this.audioCtx || this.audioCtx.state === 'suspended') {
        this.audioCtx = new AudioCtx();
      }
      
      const ctx = this.audioCtx;
      const notes = [261.63, 329.63, 392.00, 440.00, 523.25];
      const startT = ctx.currentTime + 0.05;
      
      notes.forEach((freq, idx) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, startT + idx * 0.22);
        
        gain.gain.setValueAtTime(0.15, startT + idx * 0.22);
        gain.gain.exponentialRampToValueAtTime(0.001, startT + idx * 0.22 + 0.55);
        
        osc.connect(gain);
        gain.connect(ctx.destination);
        
        osc.start(startT + idx * 0.22);
        osc.stop(startT + idx * 0.22 + 0.6);
      });

      this.isSpeaking = true;
      setTimeout(() => {
        this.isSpeaking = false;
        if (onComplete) onComplete();
      }, (notes.length * 0.22 + 0.6) * 1000);
    } catch (err) {
      this.isSpeaking = false;
      if (onComplete) onComplete();
    }
  }

  stopSpeaking() {
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
    }
    this.isSpeaking = false;
  }
}

window.i18n = new I18nManager();
